  "ch": 0,
  "m": 4,
  "kind": "case",
  "sec": "D",
  "d": 2,
  "en": "Carbohydrates are optically active polyhydroxy aldehydes or ketones or molecules that provide such units on hydrolysis. They are broadly classified into three groups : monosaccharides, oligosaccharides and polysaccharides. Monosaccharide units are held together by glycosidic linkages to form disaccharides or polysaccharides. Starch and cellulose are polysaccharides. Starch is a polymer of -glucose and consists of two components : Amylose and Amylopectin. Amylose is water soluble, having 15 – 20% of starch, whereas Amylopectin is insoluble in water, having 80 – 85% starch. Chemically, amylose is a long unbranched chain of -glucose units held together by C1 − C4 glycosidic linkage. Amylopectin is a branched chain of -glucose units held together by C1 − C4 and C1 − C6 glycosidic linkages. (a) Write two differences between Amylose and Amylopectin. 2 ^56(B)^ 19 [ ] 56B82F11 (b) (i) Classify the following into monosaccharides and disaccharides : 1 Fructose, Lactose, Glucose, Maltose OR (b) (ii) Define polysaccharide with an example. 1 (c) Name the linkage which joins two monosaccharide units. 1 SECTION E",
