  "en": "The Valence Bond Theory (VBT) explains the formation, magnetic behaviour and geometry of coordination compounds. The Crystal Field Theory (CFT) of coordination compounds is based on the effect of different crystal fields (provided by the ligands taken as point charges), on the degeneracy of d-orbital energies of the central metal atom/ion. The splitting of the d-orbitals provides different electronic arrangements in strong and weak crystal fields. Answer the following questions : (a) In octahedral crystal field, energies of which d-orbitals will be raised when ligands approach the central metal atom/ion ? Give reason in support of your answer. 2 (b) Using crystal field theory, write the electronic configuration of central metal atom/ion of the following : 1 (i) [CoF6]3– (ii) [Co(NH3)6]3+ [At. No. : Co = 27] (c) [NiCl4]2– is paramagnetic while [Ni(CO)4] is diamagnetic though both are tetrahedral. Why ? [Atomic No. : Ni = 28] 1 OR (c) Write hybridization and magnetic behaviour of the complex [Fe(CN)6]3–. [Atomic No. : Fe = 26] 1 { } ^56/1/3^ 21 SECTION – E",
