  "en": "The rate of a gaseous reaction triples when temperature is increased from 17 C to 27 C. Calculate the energy of activation for this reaction. 3 [Given : 2 303 R = 19 15 JK 1 mol 1, log 3 = 0 48] SECTION D The following questions are case-based questions. Read the case carefully and answer the questions that follow.",
