  "kind": "sa",
  "sec": "C",
  "d": 2,
  "en": "Give reasons for the following : 3 1=3 (a) Chlorine is ortho/para directing in electrophilic aromatic substitution reactions, though chlorine is an electron withdrawing group. (b) Racemic mixture is optically inactive. (c) Allyl chloride is hydrolysed more readily than n-propyl chloride. . SECTION D The following questions are case-based questions. Read the case carefully and answer the questions that follow.",
