  "en": "(a) Can sodium ethoxide and t-butyl chloride be used for the preparation of t-butyl ethyl ether ? Give suitable explanation. Justify your answer by suggesting the appropriate starting material required for preparation of t-butyl ethyl ether. 2 (b) Give the IUPAC name of above mentioned ether. 1 . SECTION D The following questions are case-based questions. Read the case carefully and answer the questions that follow.",
