  "en": "(a) (i) Account for the following : (I) MnO is basic while Mn2O7 is acidic. (II) Iron has higher enthalpy of atomization than that of copper. (III) Mn3+ is a stronger oxidising agent than Cr3+. (ii) How do you prepare potassium dichromate from sodium chromate ? Write balanced chemical equation for each step. 3+2=5 OR (b) Answer the following questions : 5×1=5 (i) Why is chemistry of actinoids more complicated as compared to lanthanoids ? (ii) + 2 o M / M E values are not regular for first row transition elements (3d series). Why ? (iii) Identify the following : (I) Oxoanion of chromium which is stable in acidic medium. (II) The lanthanoid element that exhibits +4 oxidation state. (iv) Write the products obtained on heating KMnO4. (v) Predict which of the following ions will be coloured in aqueous solution : Cu+, Sc3+, Fe2+, Ti3+, Zn2+ ^56/4/1^ 21 [ ] 5682F11",
