  "ch": 0,
  "m": 4,
  "kind": "case",
  "sec": "D",
  "d": 2,
  "en": "Alcohols and Phenols are acidic in nature. Electron withdrawing groups in phenol increase its acidic strength and electron releasing groups decrease it. Alcohols undergo nucleophilic substitution with hydrogen halides to yield alkyl halides. Dehydration of alcohols gives alkenes. On oxidation, primary alcohols yield aldehydes with mild oxidising agents and carboxylic acids with strong oxidising agents, while secondary alcohols yield ketones. Tertiary alcohols are resistant to oxidation. The presence of – OH group in phenols activates the aromatic ring towards electrophilic substitution and directs the incoming group to ortho and para positions due to resonance effect. Answer the following questions : (a) Write the mechanism of acid dehydration of ethanol to yield ethene. 2 (b) (i) Why are tertiary alcohols resistant to oxidation ? 1 OR (b) (ii) Write the structure of the major product expected from the dinitration of 3-methylphenol. 1 (c) Why is ortho-nitrophenol more acidic than ortho-methoxyphenol ? 1 ^56/4/3^ 19 [ ] 5682F11 SECTION E",
  "hi": "",
  "ans": "",
  "fig": null,
  "opts": null,
