  "en": "(a) (i) Arrange the following compounds in increasing order of their acidic strengths : CH3CHCH2COOH, CH3 – CH – COOH, CH3CH2CHCOOH | | | Br CH3 Br ^56/5/1^ 15 5682F11 [ ] (ii) Why is CH3CHO more reactive than acetone towards reaction with HCN ? (iii) Complete the equation : 3 2 2 CH H C O NH NH H + = + → – 1+1+1=3 OR (b) An organic compound with the molecular formula C8H8O forms 2,4-DNP derivative, reduces Tollens reagent and undergoes Cannizzaro reaction. On vigorous oxidation it gives Benzene-1,2-dicarboxylic acid. Identify the compound and write the reactions of compound 2,4-DNP and when it undergoes Cannizzaro reaction. 3 SECTION D The following questions are Case-based questions. Read the case carefully and answer the questions that follow.",
