  "kind": "la",
  "sec": "E",
  "d": 2,
  "en": "(a) (i) Calculate the freezing point of a solution when 10 5 g of MgBr2 was dissolved in 250 g of water, assuming MgBr2 undergoes complete dissociation. 3 (Given : Molar mass of MgBr2 = 184 g mol–1, Kf for water = 1 86 K kg mol–1) (ii) Write two differences between ideal and non-ideal solutions. 1+1 OR (b) (i) A solution is prepared by dissolving 0 025 g of potassium sulphate in 2 L of water at 27C. Assuming potassium sulphate is completely dissociated, determine its osmotic pressure. 3 (Given : R = 0 082 L atm K–1 mol–1, Molar mass of K2SO4 = 174 g mol–1) (ii) What type of azeotrope will be formed by a solution of acetone and chloroform ? Give reason. 2 ^56/5/1^ 21 5682F11 [ ]",
