  "en": "Alcohols undergo a number of reactions involving the cleavage of C – OH bond. However, phenols do not undergo reactions involving the cleavage of C – OH bond. Alcohols are weaker acids than water. Alcohols react with halogen acids to form the corresponding haloalkanes. Phenols are stronger acids than alcohols. A characteristic feature of phenols is that they undergo electrophilic substitution reactions such as halogenation, nitration, etc. Since – OH group is a strong activating group, phenol gives trisubstituted products during halogenation, nitration, etc. (a) What happens when phenol is treated with the following ? 2 (i) Br2 water (ii) Conc. HNO3 (b) (i) Write the mechanism of alcohol reacting as nucleophile in a reaction with 3 CH. 1 OR (b) (ii) Why do phenols not undergo reactions involving cleavage of C – OH bond ? 1 (c) How can you distinguish between Butan-1-ol and 2-Methylpropan-2-ol by using HCl in the presence of anhydrous ZnCl2 ? 1 .",
