  "d": 2,
  "en": "Amines are usually formed from nitro compounds, halides, amides, imides etc. They exhibit hydrogen bonding which influence their physical properties. Alkyl amines are found to be stronger bases than ammonia. In aromatic amines, electron releasing and withdrawing groups, respectively increase and decrease their basic character. Influence of the number of hydrogen atoms at nitrogen atom on the type of reactions and nature of products is responsible for identification and distinction between primary, secondary and tertiary amines. Reactivity of aromatic amines can be controlled by acylation process. 56(B)/S # 17 # P.T.O. Arrange the following : (a) (i) p-nitroaniline, p-toluidine, Aniline (in increasing order of basic strength) (ii) (C2H5)2NH, C2H5NH2, C6H5NH2 2 (in increasing order of solubility in water) (b) (i) pKb of aniline is more than that of methylamine. Why ? 1 OR (b) (ii) Write short note on Hoffmann s bromamide degradation reaction. 1 (c) Give a simple chemical test to distinguish between Methylamine and Dimethylamine. 1",
