  "d": 2,
  "en": "Temperature dependence of rate constants is described by Arrhenius equation : k = A e–Ea/RT Ea corresponds to the activation energy and A corresponds to the collision frequency. The equation clearly shows that increase of temperature or lowering of Ea will lead to increase in the rate of reaction and presence of a catalyst lowers the activation energy (Ea) by providing an alternate path for the reaction. Rate constant and order of a reaction can be determined from rate law or its integrated rate equation. (a) For a first order reaction, show that time required for 99% completion is twice the time required for the completion of 90% of the reaction. 2 (b) (i) Write two factors that affect the rate of a chemical reaction. 1 OR (b) (ii) Oxygen is available in plenty in the air, yet fuels do not burn by themselves at room temperature. Why ? 1 (c) How is activation energy affected by use of a catalyst ? 1 56(B)/S # 19 # P.T.O. SECTION E",
  "hi": "",
