  "kind": "sa",
  "sec": "C",
  "d": 2,
  "en": "Give plausible explanation for each of the following : 3 (a) Sodium hydrogen sulphite is used for separation and purification of aldehydes. (b) 2,2,6-trimethylcyclohexanone does not form cyanohydrin. (c) Only one – NH2 group of semicarbazide is involved in the formation of semicarbazone. . SECTION D The following questions are case-based questions. Read the case carefully and answer the questions that follow.",
